$ErrorActionPreference='Stop'; $desktop=[Environment]::GetFolderPath('Desktop'); $out=Join-Path $desktop '全国大学生数学建模竞赛_2021-2025_题目-优先论文-附件'
$nodes=@{'2025'='03c91a444e62eee81a3740fa97a461a6';'2024'='a0c1fb5c31d43551f08cd8ad16870444';'2023'='c74d72127066f510a5723a94b5323a26';'2022'='388239ded4b057d37b7b8e51e33fe903';'2021'='90d223833c1eb50f899aa096a66c6896'}
$idx=@{'2025'='https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/2025qgdxssxjmjslwzs/';'2024'='https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/2024qgdxssxjmjslwzs/';'2023'='https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/2023qgdxssxjmjslwzs/2023gjsbqgdxssxjmjslwzs.shtml';'2022'='https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/2022qgdxssxjmjslwzs/2022gjsbqgdxssxjmjslwzs.shtml';'2021'='https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/2021qgdxssxjmjslwzs/2021gjsbqgdxssxjmjslwzs.shtml'}
$rows=@(); foreach($year in 2021..2025){$y="$year";$yd=Join-Path $out $y;New-Item -ItemType Directory -Force $yd|Out-Null;$pp=Invoke-WebRequest "https://www.mcm.edu.cn/html_cn/node/$($nodes[$y]).html" -UseBasicParsing;$m=[regex]::Match($pp.Content,'href="(?<u>/upload_cn/node/[^"]+\.(?:zip|rar))"[^>]*>(?<n>[^<]+)');$pn=Join-Path $yd $m.Groups['n'].Value.Trim();if(!(Test-Path $pn)){Invoke-WebRequest ('https://www.mcm.edu.cn'+$m.Groups['u'].Value) -OutFile $pn -UseBasicParsing -TimeoutSec 180};$h=(Invoke-WebRequest $idx[$y] -UseBasicParsing).Content;$cm=[regex]::Matches($h,'(?is)<a[^>]+href=["''](?<u>[^"'']+)["''][^>]*>.*?(?<t>'+[regex]::Escape($y)+'.*?题论文展示.*?)</a>');$pick=@{};foreach($x in $cm){$q=[regex]::Match($x.Groups['t'].Value,'([A-E])题').Groups[1].Value;if($q -and !$pick[$q]){$pick[$q]=[uri]::new([uri]$idx[$y],$x.Groups['u'].Value).AbsoluteUri}};foreach($q in 'A','B','C','D','E'){$qd=Join-Path $yd ($q+'题');New-Item -ItemType Directory -Force $qd|Out-Null;$u=$pick[$q];$htmlp=Join-Path $qd '官方论文展示页.html';if($u -and !(Test-Path $htmlp)){curl.exe -k -L --max-time 30 -A 'Mozilla/5.0' $u -o $htmlp|Out-Null};$rows+=[pscustomobject]@{Year=$y;Question=$q;Status=$(if($u){'官方展示页已保存'}else{'缺少官方展示页'});Problem=$pn;PaperUrl=$u;Files=(Get-ChildItem $qd -File|Measure-Object).Count}}};$rows|Export-Csv (Join-Path $out '索引.csv') -NoTypeInformation -Encoding UTF8;@('# 全国大学生数学建模竞赛近五届组合包','', '范围: 2021-2025，每年 A-E。','说明: 题目附件来自竞赛官网。每题保留中国大学生在线官方论文展示页 HTML；2021 年已下载的论文逐页图片继续保留。官方展示页未提供奖项等级字段，因此未宣称为最高奖论文。','', '来源: https://www.mcm.edu.cn/html_cn/block/8579f5fce999cdc896f78bca5d4f8237.html','论文展示: https://dxs.moe.gov.cn/zx/hd/sxjm/sxjmlw/qkt_sxjm_lw_lwzs.shtml','索引: 索引.csv')|Set-Content (Join-Path $out 'README.md') -Encoding UTF8;Get-ChildItem $out -Recurse -File|Measure-Object Length -Sum; $rows|Group-Object Status|Select Name,Count
